import app.models as m
from app.database import Base, sync_engine
from sqlalchemy import inspect
from app import models
import pkgutil, importlib
for mod in pkgutil.iter_modules(models.__path__): importlib.import_module('app.models.'+mod.name)
insp=inspect(sync_engine)
for t in Base.metadata.sorted_tables:
    if not insp.has_table(t.name): print('MISSING TABLE',t.name); continue
    db={c['name']:c for c in insp.get_columns(t.name)}
    for c in t.columns:
        if c.name not in db: print('MISSING COL',t.name,c.name,c.type)
        else:
            d=db[c.name]
            if str(d['type'])!=str(c.type.compile(sync_engine.dialect)) or d['nullable']!=c.nullable: print('DIFF',t.name,c.name,d['type'],d['nullable'],'model:',c.type.compile(sync_engine.dialect),c.nullable)
    for n in db:
        if n not in t.columns: print('EXTRA DB COL',t.name,n)
"
